    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>TimesFM Forecast Evolution</h1>
            <p class="subtitle">Watch the forecast evolve as more data is added — forecasts extend to 2025-12</p>
        </header>

        <div class="chart-container">
            <canvas id="chart"></canvas>
        </div>

        <div class="controls">
            <div class="slider-container">
